#include<bits/stdc++.h>

using namespace std;
using ll=long long;

int main(){
  ll t;
  cin >> t;
  while(t--){
    ll n,s=0;
    cin >> n;
    vector<ll> r(n);
    for(auto &nx : r){
      cin >> nx;
      s+=nx;
    }
    for(ll i=1;i<n;i++){ r[i]=min(r[i],r[i-1]+1); }
    for(ll i=n-2;i>=0;i--){ r[i]=min(r[i],r[i+1]+1); }
    for(auto &nx : r){ s-=nx; }
    cout << s << "\n";
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
	int t;
	cin >> t;
	while (t--) {
		int n;
		cin >> n;
		vector<int> r(n);
		for (int &v : r) cin >> v;
		using pli = pair<long, int>;
		priority_queue<pli, vector<pli>, greater<pli>> pq; // {a[i], i} のペアを a[i] の昇順で持つ
		for (int i = 0; i < n; i++) pq.push({r[i], i});
		vector<int> a = r;
		while (!pq.empty()) {
			const auto [ai, i] = pq.top();
			pq.pop();
			if (a[i] != ai) continue; // 優先度付きキューに残っている古い情報が取り出された場合すぐに捨てる
			if (i != 0 && a[i - 1] > a[i] + 1) {
				a[i - 1] = a[i] + 1;
				pq.push({a[i - 1], i - 1});
			}
			if (i != n - 1 && a[i + 1] > a[i] + 1) {
				a[i + 1] = a[i] + 1;
				pq.push({a[i + 1], i + 1});
			}
		}
		long ans = 0;
		for (int i = 0; i < n; i++) ans += r[i] - a[i];
		cout << ans << '\n';
	}
}
